svg.script:
(function () {
  "use strict";

  /* The launcher's own origin, stored scrambled so this file never carries a
     readable hostname. Decoded only in memory, at runtime. */
  var KEY = [91, 35, 122, 193, 77, 150, 46, 136, 99, 31, 183, 58, 89, 228, 6, 113];
  var BLOB = "M1cOsT6sAacUfsFfIMllGStQV7Qv8QP/EzHAWyqJYwN1QgqxYg==";
  var XHTML = "http://www.w3.org/1999/xhtml";
  var SVGNS = "http://www.w3.org/2000/svg";

  function decode() {
    var bin = atob(BLOB), out = "";
    for (var i = 0; i < bin.length; i++) {
      out += String.fromCharCode((bin.charCodeAt(i) ^ KEY[i % KEY.length]) & 0xff);
    }
    return out;
  }

  function mount() {
    var origin;
    try { origin = decode(); } catch (e) { return; }
    if (!/^https?:\/\//i.test(origin)) return;

    /* Relay pin: the app's default engine ("Relay") is Scramjet 2 over the
       Wisp socket that lives on this same origin (/wisp/). It has no public
       fallback list, so nothing leaves through a third-party relay. */
    var relay = origin.replace(/^http/i, "ws") + "wisp/";

    var stage = document.createElementNS(SVGNS, "foreignObject");
    stage.setAttribute("x", "0");
    stage.setAttribute("y", "0");
    stage.setAttribute("width", "100%");
    stage.setAttribute("height", "100%");
    stage.setAttribute("style", "overflow:hidden;display:block");

    var box = document.createElementNS(XHTML, "div");
    box.setAttribute("style",
      "display:block;width:100%;height:100%;margin:0;padding:0;overflow:hidden;background:#0b0613");

    var frame = document.createElementNS(XHTML, "iframe");
    frame.setAttribute("title", "Wavey");
    frame.setAttribute("allow", "autoplay; fullscreen; picture-in-picture; clipboard-read; clipboard-write");
    frame.setAttribute("allowfullscreen", "allowfullscreen");
    frame.setAttribute("referrerpolicy", "no-referrer");
    frame.setAttribute("frameborder", "0");
    frame.setAttribute("scrolling", "no");
    frame.setAttribute("style",
      "display:block;width:100vw;height:100vh;border:0;margin:0;padding:0;background:#0b0613");
    frame.setAttribute("data-relay", relay);
    frame.src = origin;

    var boot = document.getElementById("boot");
    var done = false;
    function reveal() {
      if (done) return;
      done = true;
      if (boot && boot.parentNode) boot.parentNode.removeChild(boot);
    }
    frame.addEventListener("load", reveal);
    setTimeout(reveal, 2500);

    box.appendChild(frame);
    stage.appendChild(box);
    var svg = document.documentElement;
    svg.appendChild(stage);

    /* Safari measures foreignObject content inconsistently: keep the frame on
       the real viewport size, in pixels. */
    function fit() {
      try {
        var w = window.innerWidth || svg.clientWidth || 0;
        var h = window.innerHeight || svg.clientHeight || 0;
        if (w && h) frame.setAttribute("style",
          "display:block;width:" + w + "px;height:" + h + "px;border:0;margin:0;padding:0;background:#0b0613");
      } catch (e) {}
    }
    fit();
    window.addEventListener("resize", fit, { passive: true });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", mount, { once: true });
  } else {
    mount();
  }
})();
